hits.text:
magnetic bento hover effect w/ css anchor positioning

.bento {
  li:hover article { anchor-name: --a; }
  .indicator {
    position-anchor: --a;
    inset: anchor(inside);
    transition: inset var(--dur) var(--ease);
  }
}

